insert into public.collections (id, slug, name, subtitle, description, translations, cover_image_url, hero_image_url, gallery, is_featured, position) values
  ('b26beb65-3958-b40e-241b-3417aa9b4c03', 'the-tailoring-edit', 'The Tailoring Edit', 'Sharp lines, softened', 'Suiting cut close to the body and finished by hand, for the days that ask more of you.', '{"ar":{"name":"مختارات الخياطة","subtitle":"خطوط حادة بلمسة ناعمة","description":"بدلات مفصّلة بدقة ومنتهية يدوياً، للأيام التي تتطلب حضوراً أكبر."}}'::jsonb, 'https://images.unsplash.com/photo-1617137968427-85924c800a22?sat=-100', 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?sat=-100', '[{"url":"https://images.unsplash.com/photo-1617127365659-c47fa864d8bc?sat=-100","alt":"The Tailoring Edit"},{"url":"https://images.unsplash.com/photo-1594938298603-c8148c4dae35?sat=-100","alt":"The Tailoring Edit"}]'::jsonb, true, 1),
  ('0863115f-15b5-667a-ef52-d27d46b817a3', 'winter-atelier', 'Winter Atelier', 'Wool, leather, weight', 'Double-faced wool, vegetable-tanned leather and boots built to be resoled. Outerwear for the cold months.', '{"ar":{"name":"أتيليه الشتاء","subtitle":"صوف وجلد وثقل","description":"صوف مزدوج الوجه وجلد مدبوغ نباتياً وأحذية قابلة للإصلاح. ملابس خارجية للأشهر الباردة."}}'::jsonb, 'https://images.unsplash.com/photo-1539533018447-63fcce2678e3?sat=-100', 'https://images.unsplash.com/photo-1512436991641-6745cdb1723f?sat=-100', '[{"url":"https://images.unsplash.com/photo-1520975954732-35dd22299614?sat=-100","alt":"Winter Atelier"},{"url":"https://images.unsplash.com/photo-1483985988355-763728e1935b?sat=-100","alt":"Winter Atelier"}]'::jsonb, true, 2),
  ('3ce89b9e-77ec-88ac-3b77-9a8a023e7a6c', 'riviera', 'Riviera', 'Dresses for long evenings', 'Silk chiffon, cotton voile and printed crepe that move with the wind off the water.', '{"ar":{"name":"ريفييرا","subtitle":"فساتين للأمسيات الطويلة","description":"شيفون حريري وقطن خفيف وكريب مطبوع يتحرك مع نسيم البحر."}}'::jsonb, 'https://images.unsplash.com/photo-1595777457583-95e059d581b8?sat=-100', 'https://images.unsplash.com/photo-1502716119720-b23a93e5fe1b?sat=-100', '[{"url":"https://images.unsplash.com/photo-1596783074918-c84cb06531ca?sat=-100","alt":"Riviera"},{"url":"https://images.unsplash.com/photo-1496747611176-843222e1e57c?sat=-100","alt":"Riviera"}]'::jsonb, true, 3),
  ('c604aca0-6e88-7e88-db59-7dc110f3031c', 'after-dark', 'After Dark', 'Evening, considered', 'Gowns, dinner suits and the few pieces that make an entrance without trying.', '{"ar":{"name":"بعد الغروب","subtitle":"سهرة مدروسة","description":"فساتين سهرة وبدلات عشاء وقطع قليلة تلفت الأنظار دون جهد."}}'::jsonb, 'https://images.unsplash.com/photo-1612336307429-8a898d10e223?sat=-100', 'https://images.unsplash.com/photo-1566174053879-31528523f8ae?sat=-100', '[{"url":"https://images.unsplash.com/photo-1617127365659-c47fa864d8bc?sat=-100","alt":"After Dark"}]'::jsonb, false, 4);
insert into public.products (id, slug, style_code, name, description, material, care, fit, details, translations, department, category_id, price, sale_price, status, is_featured, is_new_arrival, is_best_seller, sales_count, size_guide, tags, published_at, seo_description) values ('87ed27b3-2d73-e632-6063-c90ca945faff', 'off-shoulder-column-dress', 'VW-DR-0101', 'Off-Shoulder Column Dress', 'A floor-grazing column in heavy stretch crepe. The neckline sits just off the shoulder and holds its line without boning.', '78% viscose, 22% elastane crepe', 'Dry clean or hand wash cold. Do not wring. Cool iron on reverse.', 'Close to the body. True to size.', '["Bonded neckline","Concealed back zip","Fully lined"]'::jsonb, '{"ar":{"name":"فستان طويل بأكتاف مكشوفة","description":"فستان عمودي طويل من الكريب المطاطي الثقيل، بخط عنق ينسدل عن الكتفين ويحافظ على شكله دون دعامات.","material":"كريب ٧٨٪ فسكوز و٢٢٪ إيلاستين","care":"تنظيف جاف أو غسيل يدوي بارد. لا يُعصر."}}'::jsonb, 'women', '654d18f1-8148-adbf-a51c-d148ee0f006c', 545000, null, 'active', true, false, true, 61, 'apparel', array['evening', 'gown'], '2026-05-13T15:49:07.969Z', 'A floor-grazing column in heavy stretch crepe.');
