insert into public.products (id, slug, style_code, name, description, material, care, fit, details, translations, department, category_id, price, sale_price, status, is_featured, is_new_arrival, is_best_seller, sales_count, size_guide, tags, published_at, seo_description) values ('92f23434-1efc-4361-3265-a00e9af462e7', 'pleated-chiffon-maxi-dress', 'VW-DR-0102', 'Pleated Chiffon Maxi Dress', 'Sun-ray pleats fall from a fitted bodice and open fully when you move. Two colourways, each dyed after pleating so the colour sits deep in the folds.', '100% silk chiffon, viscose lining', 'Dry clean or hand wash cold. Do not wring. Cool iron on reverse.', 'Relaxed through the skirt. Fitted bodice.', '["Sun-ray pleating","Adjustable straps","Invisible side zip"]'::jsonb, '{"ar":{"name":"فستان شيفون طويل بطيات","description":"طيات شعاعية تنساب من صدار محدد وتنفتح بالكامل مع الحركة. لونان، صُبغ كل منهما بعد التطيات ليتعمق اللون في الثنايا.","material":"شيفون حرير ١٠٠٪ مع بطانة فسكوز","care":"تنظيف جاف أو غسيل يدوي بارد. لا يُعصر."}}'::jsonb, 'women', '654d18f1-8148-adbf-a51c-d148ee0f006c', 500000, 375000, 'active', true, true, false, 3, 'apparel', array['summer', 'maxi'], '2026-11-02T15:49:07.969Z', 'Sun-ray pleats fall from a fitted bodice and open fully when you move.');
